from pathlib import Path
import json,html,re,csv
R=Path(__file__).resolve().parent
parts=[r for r in json.loads((R/'scene.json').read_text()) if not r['component']]
e=html.escape
old=(R/'index.html').read_text(encoding='utf-8')
if 'data-r11-generated' in old:
    old=(R.parent/'revision-10'/'index.html').read_text(encoding='utf-8')
style=old.split('<style>')[1].split('</style>')[0]
body=old[old.index('<section id="cases">'):old.index('<footer>')]
scripts=old[old.index('<script>'):old.index('</script>')+9]
body=body.replace('revision10','revision11').replace('Revision 10','Revision 11')
def fig(file,caption):
    return f'<figure><a href="previews/{file}" target="_blank"><img src="previews/{file}" loading="lazy" alt="{e(caption)}"></a><figcaption>{caption}</figcaption></figure>'
layout=json.loads((R/'LIGHTING_LAYOUT.json').read_text())
svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 780 650"><rect width="780" height="650" fill="#172029"/><g font-family="Arial" fill="#ecede7"><text x="30" y="38" font-size="23">MAIN · FOUR LIGHT SOURCES</text><text x="30" y="65" font-size="15" fill="#b2c2cc">Top plan · nominal positions · not a breadboard wiring diagram</text></g><g transform="translate(75 95) scale(2.6)">']
svg+=['<rect width="234" height="180" rx="20" fill="#4c392b" stroke="#c7a171" stroke-width="1"/>','<rect x="34" y="12" width="166" height="55" rx="2" fill="#d6d3c7"/>','<rect x="100" y="24" width="60" height="32" fill="#307d72" opacity=".8" stroke="#93c9bb" stroke-dasharray="2 2"/>','<text x="112" y="42" font-family="Arial" font-size="5" fill="white">ESP32 SPACE</text>','<circle cx="117" cy="108" r="26" fill="#271f35" stroke="#ad8ee1" stroke-width="2"/>','<circle cx="117" cy="108" r="11" fill="none" stroke="#ad8ee1"/>','<text x="109" y="110" font-family="Arial" font-size="6" fill="#d8c9f5">RGB</text>']
for c in layout['channels']:
    points=' '.join(f'{x},{y}' for x,y in c['path_xy_mm']);x,y=c['led_xy_mm']
    svg+=[f'<polyline points="{points}" fill="none" stroke="#60d78b" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>',f'<circle cx="{x}" cy="{y}" r="4" fill="#a7ffc7" stroke="#173d29"/>',f'<text x="{x-5}" y="{y+12}" font-family="Arial" font-size="6" fill="#0c2d1c">{c["tag"]}</text>']
svg+=['<text x="77" y="7" font-family="Arial" font-size="5" fill="#eee2cf">REAR / USB SHUTTER</text>','<text x="75" y="170" font-family="Arial" font-size="6" fill="#eee2cf">FRONT / POWER BUTTON</text></g>','<text x="30" y="605" font-family="Arial" font-size="16" fill="#c8d1d6">Green paths = lid windows. Four circles = green LEDs on the breadboard.</text>','<text x="30" y="632" font-family="Arial" font-size="16" fill="#c8d1d6">RGB uses its own opaque chamber; green and RGB control stay independent.</text></svg>']
(R/'previews'/'led-layout.svg').write_text(''.join(svg))
lighting='''<section id="lighting"><h2>Four green runes. One steady rhythm.</h2><p>Four diffused green LEDs sit near the corners of Main’s full-size breadboard. Each feeds its own enclosed light well and short rune path. Separate frosted inserts spread the light; the bronze bezel captures each insert without screws.</p><div class="card"><div class="controls"><button class="active" onclick="lightView(this,'breathing')">Breathing · 4 seconds</button><button onclick="lightView(this,'on')">Green + RGB</button><button onclick="lightView(this,'rgb')">RGB only</button><button onclick="lightView(this,'off')">All off</button></div><div id="light-stage" class="light-stage breathing"><img id="light-base" src="previews/lighting-rgb-only.png" alt="Main with isolated RGB emblem"><img id="light-overlay" src="previews/lighting-on.png" alt="Green rune lighting appearance"></div><p class="muted">Appearance preview from CAD. This illustrates the intended fading pattern; brightness and uniformity are not measured optical results. The RGB emblem stays independent.</p></div><div class="grid">'''
lighting+=fig('led-layout.svg','G1–G4 locations and the matching light paths. The provisional ESP32 space moves to the centre of the breadboard, clear of the four wells.')
lighting+=fig('lighting-breadboard.png','Actual base geometry with four nominal green LED references. Each LED needs its own current-limiting resistor. Check real hole rows and lead bends.')
lighting+=fig('lighting-underside.png','Underside: four enclosed light galleries and feed wells. Keep wires out of these wells and away from the lid latches.')
lighting+=fig('lighting-exploded.png','Assembly: place each translucent lens over its window, then press its matching bronze bezel into the two lid slots. Release the tabs from inside for service.')
lighting+='</div><h3 style="margin-top:35px">An isolated central RGB chamber</h3><p>The existing 52 mm cup’s side opening is closed. A second opaque skirt and removable quarter-turn cap shield the lower LED connection. Two offset wire passages reduce direct light escape. Use a flexible wire extension and disconnect it before rotating the cap.</p><div class="grid">'
lighting+=fig('lighting-rgb-shield.png','Shield cap removed beneath the existing RGB LED keeper. The keeper retains the LED; the new cap shields its underside.')
lighting+=fig('lighting-rgb-section.png','Cutaway inspection view: cylindrical wall, LED seat, and the offset wire passages in the shield. The cut faces are open for this view only.')
lighting+=fig('lighting-coupon.png','Start here: the cropped G1 test piece with its real lens and bezel. Check the material, light distribution and clips before printing the complete lid.')
lighting+='''</div><div class="status">Print one optical sample first. Opaque bronze may block or leak light depending on its formulation and wall thickness. The lenses require translucent material or a fitted frosted insert. LED brightness, hotspots, snap retention and battery runtime remain physical tests.</div><div class="downloads"><a href="fit-tests/M-lighting-G1-coupon-Soham-Basanwar.stl">G1 test body · STL</a><a href="R11_PRINT_NOTES.md">How to print the test</a></div><h3 style="margin-top:28px">Fade control and wiring</h3><p>A nonblocking four-second fade controls all four green LEDs together through one suitable MOSFET. Each LED has its own resistor. The RGB status LED keeps its own circuit. Choose a verified unused PWM pin; the helper has not been integrated into or flashed to the game firmware.</p><div class="downloads"><a href="lighting/README.md">Wiring, current limits &amp; installation</a><a href="lighting/BreathingAccent.h">Fade helper</a><a href="LIGHTING_LAYOUT.json">Nominal positions</a></div></section>'''
idsection='<section id="identify"><h2>Pick the code. Match the part.</h2><p>E = Explorer, A = Architect, M = Main. Codes match the STL filenames and these actual CAD thumbnails. Recessed codes are added only where a readable noncontact face is available. Small, flexible, optical or fit-sensitive pieces use their bag label. Existing Soham Basanwar / SB marks remain.</p><div class="downloads"><a href="PART_LABELS.html" target="_blank">Print sorting labels</a><a href="PARTS.csv">Full parts file</a></div><p class="muted">Put each part straight from the print bed into its labelled bag or compartment. Keep alternate inserts in separate labelled bags; do not mix them with the nominal set. Pictures are individually scaled.</p>'
idsection+='<div class="grid three">'+''.join(fig('id-'+code+'.png',code+' · actual recessed assembly code') for code in ['E01','E04','M02','M23','M27','M31'])+'</div>'
labels='<!doctype html><html><head><meta charset="utf-8"><title>R11 sorting labels</title><style>body{font:12px Arial;margin:16px;color:#111}section{break-after:page}.labels{display:grid;grid-template-columns:repeat(4,1fr);gap:4mm}.label{border:1px dashed #555;padding:3mm;height:27mm;box-sizing:border-box;break-inside:avoid}.code{font-size:22px;font-weight:bold}.small{font-size:10px}@page{size:A4;margin:12mm}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()">Print these sorting labels</button>'
for role in ['explorer','architect','main']:
    pp=sorted([r for r in parts if r['role']==role],key=lambda r:r['assembly_code'])
    idsection+=f'<h3 style="margin-top:35px">{role.title()} · {len(pp)} printed pieces</h3><div class="parts-grid">'
    labels+=f'<section><h2>{role.upper()} · Soham Basanwar · Revision 11</h2><div class="labels">'
    for i,r in enumerate(pp):
        if i and i%32==0:labels+=f'</div></section><section><h2>{role.upper()} · continued · Revision 11</h2><div class="labels">'
        code=r['assembly_code'];title=r['name'].replace('_',' ');marked=r.get('id_location') is not None
        idsection+=f'<article class="part-card"><a href="prototype-stl/{e(r["file"])}"><img src="previews/part-thumbnails/{role}-{r["name"]}.png" loading="lazy" alt="{code} {e(title)}"><div class="part-code">{code}</div><div>{e(title)}</div></a><small>{"Code engraved" if marked else "Use coded bag / tray"}</small></article>'
        labels+=f'<div class="label"><div class="code">{code}</div>{e(title)}<div class="small">Soham Basanwar · qty 1</div></div>'
    idsection+='</div>';labels+='</div></section>'
idsection+='</section>';labels+='</body></html>'
(R/'PART_LABELS.html').write_text(labels,encoding='utf-8')
extra='''.light-stage{position:relative}.light-stage img{width:100%;display:block;border-radius:12px}.light-stage img+img{position:absolute;inset:0;opacity:0}.light-stage.breathing img+img{animation:breathe 4s ease-in-out infinite}.light-stage.on img+img{opacity:1}@keyframes breathe{0%,100%{opacity:0}50%{opacity:1}}@media(prefers-reduced-motion:reduce){.light-stage.breathing img+img{animation:none;opacity:.6}}.parts-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.part-card{background:#1b2026;border:1px solid #343d47;border-radius:12px;padding:12px;overflow:hidden}.part-card img{width:100%;display:block}.part-code{font-size:24px;font-weight:700;letter-spacing:.08em;color:#a7e8bc}.part-card small{display:block;color:#aeb8c4;margin-top:8px}@media(max-width:760px){.parts-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}'''
nav='<nav><a href="#lighting">New lighting</a><a href="#cases">Three enclosures</a><a href="#adjust">Adjust &amp; lock</a><a href="#controls">Control fittings</a><a href="#gate">Gate</a><a href="#identify">Find a part</a><a href="#engraving">Owner engraving</a></nav>'
header=f'<main><div class="eyebrow">Soham Basanwar · CAD Revision 11</div><h1>Light the maze.<br>Find every part.</h1><p class="lead">Four green rune accents, a shielded RGB portal and an illustrated assembly code for every printed piece.</p><div class="chips"><span class="chip">{len(parts)} installed printed pieces</span><span class="chip">4 green LEDs on Main</span><span class="chip">Screwless service access</span></div><p class="status">Digital prototype. Component dimensions are nominal; physical fit, optical performance, flexure strength and powered operation remain unverified. Earlier adjustment and gate instructions are retained below.</p>'
footer='<footer><p>Revision 10 is preserved. Use the Revision 11 lid, matching light parts and current assembly map together. No additional software purchase is required.</p><div class="downloads"><a href="README.md">Read me</a><a href="R11_PRINT_NOTES.md">Lighting print &amp; assembly guide</a><a href="PRINT_AND_ASSEMBLY.md">Existing mechanisms</a><a href="REVIEW_VALIDATION.json">Digital checks</a>'+''.join(f'<a href="cad/{role}-revision11.FCStd">{role.title()} · FreeCAD</a>' for role in ['explorer','architect','main'])+'</div></footer></main>'
js='''<script>function lightView(b,mode){activate(b);let stage=document.getElementById('light-stage');stage.classList.remove('breathing','on');document.getElementById('light-base').src='previews/lighting-'+(mode==='off'?'off':'rgb-only')+'.png';if(mode==='breathing'||mode==='on')stage.classList.add(mode)}</script>'''
output='<!doctype html><html lang="en" data-r11-generated="true"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dual-Reality Maze · Revision 11</title><style>'+style+extra+'</style></head><body>'+nav+header+lighting+body+idsection+footer+scripts+js+'</body></html>'
(R/'index.html').write_text(output,encoding='utf-8')
print('R11 guide and printable labels generated:',len(parts),'parts')
